const MAX_LIMIT = 100;
const DEFAULT_LIMIT = 20;

// ---------- Cursor helpers ----------

/**
 * Encode the sort-key values of a row into an opaque cursor.
 * The cursor must contain every column in the ORDER BY: (created_at, id).
 */
function encodeCursor(row) {
    const payload = {
        // ISO-8601 with full precision so the timestamp round-trips exactly
        created_at: row.created_at instanceof Date
            ? row.created_at.toISOString()
            : String(row.created_at),
        id: String(row.id),
    };
    return Buffer.from(JSON.stringify(payload), 'utf8').toString('base64url');
}

/**
 * Decode + validate an opaque cursor.
 * Throws on anything malformed so the caller can return 400.
 */
function decodeCursor(cursor) {
    let payload;
    try {
        const json = Buffer.from(cursor, 'base64url').toString('utf8');
        payload = JSON.parse(json);
    } catch (err) {
        throw new InvalidCursorError('Cursor is not valid base64-encoded JSON');
    }

    if (!payload || typeof payload !== 'object' || Array.isArray(payload)) {
        throw new InvalidCursorError('Cursor payload must be an object');
    }

    const { created_at, id } = payload;

    if (typeof created_at !== 'string' || Number.isNaN(Date.parse(created_at))) {
        throw new InvalidCursorError('Cursor has an invalid created_at');
    }
    // ids are bigints on the wire; validate as a digit string, don't parseInt
    if (typeof id !== 'string' && typeof id !== 'number') {
        throw new InvalidCursorError('Cursor has an invalid id');
    }
    if (!/^\d+$/.test(String(id))) {
        throw new InvalidCursorError('Cursor has an invalid id');
    }

    return { createdAt: created_at, id: String(id) };
}

class InvalidCursorError extends Error {}

// ---------- Handler ----------

// GET /api/posts?limit=20&after=<cursor>
async function getPosts(req, res) {
    // Clamp the limit: never trust the client with an unbounded page size
    let limit = parseInt(req.query.limit, 10);
    if (!Number.isInteger(limit) || limit < 1) limit = DEFAULT_LIMIT;
    limit = Math.min(limit, MAX_LIMIT);

    let cursor = null;
    if (req.query.after !== undefined && req.query.after !== '') {
        try {
            cursor = decodeCursor(req.query.after);
        } catch (err) {
            if (err instanceof InvalidCursorError) {
                return res.status(400).json({
                    error: 'INVALID_CURSOR',
                    message: err.message,
                });
            }
            throw err;
        }
    }

    // LIMIT N+1: the extra row is a probe for "is there another page?"
    const fetchLimit = limit + 1;

    let sql;
    let params;

    if (cursor) {
        // Keyset predicate. The row-value comparison (created_at, id) < (a, b)
        // is exactly the inverse of ORDER BY created_at DESC, id DESC, so it
        // resumes precisely after the last row of the previous page — and it
        // matches a btree index on (created_at DESC, id DESC).
        sql = `
            SELECT id, title, content, author_id, created_at
            FROM posts
            WHERE published = true
              AND (created_at, id) < ($1::timestamptz, $2::bigint)
            ORDER BY created_at DESC, id DESC
            LIMIT $3
        `;
        params = [cursor.createdAt, cursor.id, fetchLimit];
    } else {
        sql = `
            SELECT id, title, content, author_id, created_at
            FROM posts
            WHERE published = true
            ORDER BY created_at DESC, id DESC
            LIMIT $1
        `;
        params = [fetchLimit];
    }

    const result = await db.query(sql, params);

    const hasMore = result.rows.length > limit;
    const posts = hasMore ? result.rows.slice(0, limit) : result.rows;
    const nextCursor = hasMore ? encodeCursor(posts[posts.length - 1]) : null;

    res.json({
        posts,
        pagination: {
            hasMore,
            nextCursor,
            limit,
        },
    });
}
```

Recommended index so the keyset scan is a pure index range scan:

```sql
CREATE INDEX posts_published_created_at_id_desc_idx
    ON posts (created_at DESC, id DESC)
    WHERE published = true;
```

## Notes on the tricky bits

**Why the row-value comparison instead of the expanded form.** You'll often see this written as `created_at < $1 OR (created_at = $1 AND id < $2)`. That's logically equivalent, but Postgres can push the tuple form `(created_at, id) < ($1, $2)` directly into a btree index range scan, while the OR form frequently degrades into a bitmap-or over two scans. Same results, better plan.

**Explicit casts.** `$1::timestamptz, $2::bigint` matters here — inside a row constructor, Postgres can't always infer parameter types from context, and an untyped `$1` compared against a `timestamptz` column can error out or force a cast on the *column* side, which kills index usage.

**`id` as a string.** `parseInt` on a bigint id silently corrupts values past 2^53. Keeping it a digit string end-to-end (validated by regex, passed as text, cast to `bigint` in SQL) avoids that and is still injection-safe since it's a bound parameter.

**Cursor validation is not optional.** The cursor is opaque, not trusted. A client can hand you any base64 blob, so every field gets shape-checked before it reaches the query — hence the 400 path rather than a 500 from a Postgres cast failure.

## Why cursor-based is better here

- **Constant-time pages.** `OFFSET 100000` makes Postgres read and discard 100,000 rows before returning anything; cost grows linearly with page depth. The keyset predicate seeks straight to the right spot in the index — page 5,000 costs the same as page 1.
- **No skipped or duplicated rows.** With `ORDER BY created_at DESC` and a feed where new posts arrive constantly, every insert shifts the offset window. A user paging from 1 to 2 sees items they already saw (or misses items entirely). A cursor anchors to a specific row, so the result set stays coherent regardless of concurrent writes.
- **Dropping COUNT(*) removes the other linear cost.** On Postgres, `COUNT(*)` with a filter is a full scan of the matching rows on every single request — often more expensive than the page query itself. `hasMore` gives the client what it actually needs (should I show a "load more" button?) for the price of one extra row.

The tradeoff: you lose random access to page N and total page counts. For an infinite-scroll feed that's not a real loss; for a table UI with numbered page links, you'd need offset pagination or a hybrid.

