const crypto = require('crypto'); // not strictly needed, but handy if you later want signed cursors

// --- Cursor helpers ---------------------------------------------------

/**
 * Encode a (created_at, id) pair into an opaque base64 cursor string.
 */
function encodeCursor(createdAt, id) {
    const payload = JSON.stringify({
        created_at: createdAt instanceof Date ? createdAt.toISOString() : createdAt,
        id,
    });
    return Buffer.from(payload, 'utf8').toString('base64');
}

/**
 * Decode a base64 cursor string back into { created_at, id }.
 * Throws if the cursor is malformed, missing fields, or has the wrong types.
 */
function decodeCursor(cursor) {
    let decoded;
    try {
        decoded = Buffer.from(cursor, 'base64').toString('utf8');
    } catch (err) {
        throw new Error('Invalid cursor encoding');
    }

    let parsed;
    try {
        parsed = JSON.parse(decoded);
    } catch (err) {
        throw new Error('Invalid cursor payload');
    }

    if (
        !parsed ||
        typeof parsed.created_at !== 'string' ||
        (typeof parsed.id !== 'string' && typeof parsed.id !== 'number')
    ) {
        throw new Error('Invalid cursor shape');
    }

    const createdAtDate = new Date(parsed.created_at);
    if (Number.isNaN(createdAtDate.getTime())) {
        throw new Error('Invalid cursor timestamp');
    }

    return { created_at: parsed.created_at, id: parsed.id };
}

// --- Route handler ------------------------------------------------------

// GET /api/posts?limit=20&after=<cursor>
async function getPosts(req, res) {
    const limit = Math.min(parseInt(req.query.limit) || 20, 100); // cap to protect the DB
    const afterRaw = req.query.after;

    let cursor = null;
    if (afterRaw) {
        try {
            cursor = decodeCursor(afterRaw);
        } catch (err) {
            return res.status(400).json({ error: 'Invalid pagination cursor' });
        }
    }

    let result;
    if (cursor) {
        // Keyset condition for compound (created_at DESC, id DESC) ordering:
        // fetch rows strictly "after" the cursor in that sort order.
        result = await db.query(
            `SELECT id, title, content, author_id, created_at
             FROM posts
             WHERE published = true
               AND (created_at, id) < ($1, $2)
             ORDER BY created_at DESC, id DESC
             LIMIT $3`,
            [cursor.created_at, cursor.id, limit + 1]
        );
    } else {
        result = await db.query(
            `SELECT id, title, content, author_id, created_at
             FROM posts
             WHERE published = true
             ORDER BY created_at DESC, id DESC
             LIMIT $1`,
            [limit + 1]
        );
    }

    const hasMore = result.rows.length > limit;
    const posts = hasMore ? result.rows.slice(0, limit) : result.rows;

    const nextCursor = hasMore
        ? encodeCursor(posts[posts.length - 1].created_at, posts[posts.length - 1].id)
        : null;

    res.json({
        posts,
        pagination: {
            hasMore,
            nextCursor,
            limit,
        },
    });
}

module.exports = { getPosts, encodeCursor, decodeCursor };
```

### Notes on the SQL

- `(created_at, id) < ($1, $2)` is a **row-value comparison** — Postgres evaluates it lexicographically, exactly matching `ORDER BY created_at DESC, id DESC`: it means "created_at is earlier, or created_at is equal and id is smaller." This is the standard keyset-pagination trick and correctly handles ties in `created_at`.
- Make sure there's a composite index `(created_at DESC, id DESC)` (or `(published, created_at DESC, id DESC)` including the filter column) so this becomes an efficient index range scan rather than a sequential scan + sort.
- `id` should be a type with a **total, stable order** (bigint/UUID with a real ordering guarantee) — ties in `created_at` alone would break pagination without it.

## Why cursor-based pagination is better here

1. **No OFFSET performance cliff**: `OFFSET N` forces Postgres to scan and discard the first `N` rows on every request. As `page` grows on a large `posts` table, this gets linearly slower. The keyset `WHERE (created_at, id) < (...)` uses the index to jump straight to the right spot regardless of how "deep" the page is — O(log n) instead of O(n).
2. **No COUNT(*) tax**: `COUNT(*)` on a large filtered table is a full scan (or at best an index-only scan) that gets more expensive as the table grows, and it was being run on *every single page request* just to compute `totalPages`. Dropping it removes the most expensive part of the original query.
3. **Stable results under concurrent writes**: with offset pagination, if new posts are inserted while a user pages through, rows can shift between pages (duplicates or skipped items). Cursor pagination anchors to a specific `(created_at, id)` value, so results stay consistent even as new rows are inserted at the top.
4. **Opaque, tamper-resistant contract**: base64-encoding the cursor as JSON keeps the pagination state as an implementation detail the client just passes back, letting you change the underlying fields later without breaking the API shape.

The trade-off: you lose "jump to page N" / total page count — this model only supports sequential forward paging, which fits infinite-scroll/feed-style UIs (like a posts list) very well but not classic numbered pagination UI.

