async function getPosts(req, res) {
    const limit = Math.min(Math.max(parseInt(req.query.limit, 10) || 20, 1), 100);
    const after = req.query.after;

    let cursor = null;
    if (after !== undefined && after !== null && after !== '') {
        try {
            cursor = decodeCursor(after);
        } catch {
            return res.status(400).json({ error: 'Invalid or malformed cursor' });
        }
    }

    // LIMIT N+1 to detect hasMore without a COUNT
    const fetchLimit = limit + 1;
    let result;

    if (cursor) {
        // Compound cursor: (created_at DESC, id DESC)
        // "after" means strictly older than the cursor row in that order
        result = await db.query(
            `SELECT id, title, content, author_id, created_at
             FROM posts
             WHERE published = true
               AND (
                 created_at < $1
                 OR (created_at = $1 AND id < $2)
               )
             ORDER BY created_at DESC, id DESC
             LIMIT $3`,
            [cursor.created_at, cursor.id, fetchLimit]
        );
    } else {
        // First page — no cursor filter
        result = await db.query(
            `SELECT id, title, content, author_id, created_at
             FROM posts
             WHERE published = true
             ORDER BY created_at DESC, id DESC
             LIMIT $1`,
            [fetchLimit]
        );
    }

    const rows = result.rows;
    const hasMore = rows.length > limit;
    const posts = hasMore ? rows.slice(0, limit) : rows;

    let nextCursor = null;
    if (hasMore && posts.length > 0) {
        const last = posts[posts.length - 1];
        nextCursor = encodeCursor(last.created_at, last.id);
    }

    res.json({
        posts,
        pagination: {
            hasMore,
            nextCursor,
            limit,
